//! Cargo-driven `cdrom.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is cdrom-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_FxDriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "FxDriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "FxDriverEntry", 0x7ffb00000000u64),
        o => panic!("cdrom-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "-Wl,--whole-archive", "body", "-Wl,--no-whole-archive", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:chkstk", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        "x86_64" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "-Wl,--whole-archive", "body", "-Wl,--no-whole-archive", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        "aarch64" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "-Wl,--whole-archive", "body", "-Wl,--no-whole-archive", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:chkstk", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/storage/class/cdrom",
        "drivers/storage/class/cdrom",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/wdf/include/kmdf/1.17",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "DEBUG_USE_KDPRINT",
        "NTDDI_VERSION=0x06030000",
        "NTKRNLVISTA",
        "WDF_DEVICE_NO_WDMSEC_H",
        "WINVER=0x502",
        "_WIN32_WINNT=0x603",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=-sse,-sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("cdrom-rust")
        .rust_user_target()
        .c_from_compile_db("cdrom_shims", &["drivers/storage/class/cdrom/guid.c", "drivers/storage/class/cdrom/rust_dbgprint_shim.c"])
        .rc("drivers/storage/class/cdrom/cdrom.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("sdk/lib/drivers/wdfldr/wdfldr.spec", "wdfldr.sys", "wdfldr")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
